"""Client that posts records to the ingestion API."""
import json
import os
import urllib.error
import urllib.request

# The ingestion endpoint is supplied through the environment when the client
# is deployed to the shared job host. It is intentionally not stored in this
# repository.
ENDPOINT = (
    os.environ.get("INGESTION_ENDPOINT")
    or os.environ.get("INGESTION_API")
    or os.environ.get("INGESTION_API_URL")
    or os.environ.get("INGESTION_URL")
    or ""
).strip()


def load_records(path="records.json"):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def post_records(endpoint, records):
    accepted = 0
    for record in records:
        body = json.dumps(record).encode("utf-8")
        req = urllib.request.Request(
            endpoint, data=body, headers={"Content-Type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if 200 <= resp.status < 300:
                    accepted += 1
        except (urllib.error.HTTPError, urllib.error.URLError):
            # A rejected record (or a transient network error) should not
            # prevent the remaining records from being posted.
            continue
    return accepted


def main():
    if not ENDPOINT:
        raise SystemExit(
            "No ingestion endpoint configured. Set INGESTION_ENDPOINT "
            "(or INGESTION_API_URL)."
        )
    records = load_records()
    accepted = post_records(ENDPOINT, records)
    print(f"accepted {accepted}/{len(records)}")


if __name__ == "__main__":
    main()
